import XCTest
@testable import Detour

/// Replays content/fsrs-test-vectors.json, which is generated by the web app's ts-fsrs. The Swift port must match it.
final class FSRSTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Params: Decodable {
            let request_retention: Double
            let maximum_interval: Int
            let w: [Double]
        }
        struct Case: Decodable {
            let name: String
            let steps: [Step]
            let expected: [Expected]
        }
        struct Step: Decodable {
            enum Wait: Decodable {
                case due
                case days(Int)
                init(from decoder: Decoder) throws {
                    let c = try decoder.singleValueContainer()
                    if let s = try? c.decode(String.self), s == "due" {
                        self = .due
                    } else {
                        self = .days(try c.decode(Int.self))
                    }
                }
            }
            let rating: Int
            let wait: Wait
        }
        struct Expected: Decodable {
            let at_offset_ms: Int64
            let interval_ms: Int64
            let stability: Double
            let difficulty: Double
            let scheduled_days: Int
            let elapsed_days: Int
            let reps: Int
            let lapses: Int
            let state: Int
        }
        let parameters: Params
        let cases: [Case]
    }

    private func loadVectors() throws -> Vectors {
        let bundle = Bundle(for: FSRSTests.self)
        let url = try XCTUnwrap(bundle.url(forResource: "fsrs-test-vectors", withExtension: "json"), "test vectors not bundled")
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testMatchesWebSchedulerVectors() throws {
        let vectors = try loadVectors()
        let fsrs = FSRS(w: vectors.parameters.w, requestRetention: vectors.parameters.request_retention, maximumInterval: vectors.parameters.maximum_interval)
        let first: Int64 = 1_800_000_000_000

        XCTAssertFalse(vectors.cases.isEmpty)
        for c in vectors.cases {
            var card = FSRSCard(dueMs: first)
            var at = first
            for (i, step) in c.steps.enumerated() {
                switch step.wait {
                case .due: break
                case .days(let n): at = i == 0 ? first + Int64(n - 1) * FSRS.dayMs : at + Int64(n) * FSRS.dayMs
                }
                card = fsrs.next(card, nowMs: at, grade: FSRSGrade(rawValue: step.rating)!)
                let e = c.expected[i]
                let label = "\(c.name)[\(i)]"
                XCTAssertEqual(at - first, e.at_offset_ms, "\(label) review time")
                XCTAssertEqual(card.dueMs - at, e.interval_ms, "\(label) interval")
                XCTAssertEqual(card.stability, e.stability, accuracy: 1e-6, "\(label) stability")
                XCTAssertEqual(card.difficulty, e.difficulty, accuracy: 1e-6, "\(label) difficulty")
                XCTAssertEqual(card.scheduledDays, e.scheduled_days, "\(label) scheduled days")
                XCTAssertEqual(card.elapsedDays, e.elapsed_days, "\(label) elapsed days")
                XCTAssertEqual(card.reps, e.reps, "\(label) reps")
                XCTAssertEqual(card.lapses, e.lapses, "\(label) lapses")
                XCTAssertEqual(card.state.rawValue, e.state, "\(label) state")
                at = card.dueMs
            }
        }
    }

    func testJavaScriptRoundingSemantics() {
        XCTAssertEqual(FSRS.jsRound(2.5), 3)
        XCTAssertEqual(FSRS.jsRound(-2.5), -2)
        XCTAssertEqual(FSRS.jsRound(2.4), 2)
        XCTAssertEqual(FSRS.roundTo(1.234567891, 8), 1.23456789, accuracy: 1e-12)
    }
}
